import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { MockAgent, setGlobalDispatcher } from 'undici';
import { ERROR_CODES } from '../src/errors.js';
import {
  HttpResponseError,
  createHttpClient,
  paginatePages,
  type HttpClient,
} from '../src/http.js';

describe('requestJson', () => {
  let agent: MockAgent;
  let client: HttpClient;
  const sleepCalls: number[] = [];
  const logLines: string[] = [];

  const sleep = async (ms: number): Promise<void> => {
    sleepCalls.push(ms);
  };

  beforeEach(() => {
    agent = new MockAgent();
    agent.disableNetConnect();
    setGlobalDispatcher(agent);
    client = createHttpClient({ sleep, onLog: (line) => logLines.push(line) });
    sleepCalls.length = 0;
    logLines.length = 0;
  });

  afterEach(async () => {
    await agent.close();
  });

  it('解析 200 JSON 响应', async () => {
    const pool = agent.get('https://api.example.com');
    pool
      .intercept({ path: '/ok', method: 'GET' })
      .reply(200, { hello: 'world' }, { headers: { 'content-type': 'application/json' } });

    const body = await client.requestJson<{ hello: string }>('https://api.example.com/ok', {});
    expect(body).toEqual({ hello: 'world' });
  });

  it('401 不重试并抛出 HttpResponseError', async () => {
    const pool = agent.get('https://api.example.com');
    pool.intercept({ path: '/unauth', method: 'GET' }).reply(401, { message: 'bad token' });

    await expect(
      client.requestJson('https://api.example.com/unauth', { token: 'ghp_secret_token_value' }),
    ).rejects.toMatchObject({ status: 401 });
    expect(sleepCalls).toHaveLength(0);
  });

  it('500 恰好重试 3 次，退避 1s/2s/4s', async () => {
    const pool = agent.get('https://api.example.com');
    let hits = 0;
    pool.intercept({ path: '/flaky', method: 'GET' }).reply(() => {
      hits += 1;
      return { statusCode: 500, data: 'err' };
    });

    await expect(client.requestJson('https://api.example.com/flaky', {})).rejects.toBeInstanceOf(
      HttpResponseError,
    );
    expect(hits).toBe(4);
    expect(sleepCalls).toEqual([1000, 2000, 4000]);
  });

  it('429 在重试后成功', async () => {
    const pool = agent.get('https://api.example.com');
    let hits = 0;
    pool.intercept({ path: '/rate', method: 'GET' }).reply(() => {
      hits += 1;
      if (hits < 3) return { statusCode: 429, data: 'slow down' };
      return {
        statusCode: 200,
        data: JSON.stringify({ ok: true }),
        responseOptions: { headers: { 'content-type': 'application/json' } },
      };
    });

    const body = await client.requestJson<{ ok: boolean }>('https://api.example.com/rate', {});
    expect(body).toEqual({ ok: true });
    expect(hits).toBe(3);
    expect(sleepCalls).toEqual([1000, 2000]);
  });

  it('网络错误按可重试策略退避', async () => {
    const pool = agent.get('https://api.example.com');
    let hits = 0;
    pool.intercept({ path: '/net', method: 'GET' }).reply(() => {
      hits += 1;
      if (hits < 2) {
        throw new Error('socket reset');
      }
      return {
        statusCode: 200,
        data: JSON.stringify({ recovered: true }),
        responseOptions: { headers: { 'content-type': 'application/json' } },
      };
    });

    const body = await client.requestJson<{ recovered: boolean }>('https://api.example.com/net', {});
    expect(body).toEqual({ recovered: true });
    expect(sleepCalls).toEqual([1000]);
  });

  it('日志中掩码长度大于 8 的 token', async () => {
    const pool = agent.get('https://api.example.com');
    pool.intercept({ path: '/t', method: 'GET' }).reply(200, { ok: true });

    await client.requestJson('https://api.example.com/t', {
      token: '12345678901',
      headers: { authorization: 'Bearer 12345678901' },
    });

    const joined = logLines.join('\n');
    expect(joined).not.toContain('12345678901');
    expect(joined).toMatch(/1{3}\*{3,}1{3}/);
  });

  it('404 不重试', async () => {
    const pool = agent.get('https://api.example.com');
    let hits = 0;
    pool.intercept({ path: '/missing', method: 'GET' }).reply(() => {
      hits += 1;
      return { statusCode: 404, data: 'nope' };
    });

    await expect(client.requestJson('https://api.example.com/missing', {})).rejects.toMatchObject({
      status: 404,
    });
    expect(hits).toBe(1);
    expect(sleepCalls).toHaveLength(0);
  });
});

describe('paginatePages', () => {
  it('合并各页 items', async () => {
    const pages = [
      { items: [1, 2], hasNext: true },
      { items: [3], hasNext: false },
    ];
    let page = 0;
    const all = await paginatePages({
      fetchPage: async (p) => {
        expect(p).toBe(page + 1);
        const chunk = pages[page];
        page += 1;
        return chunk!;
      },
    });
    expect(all).toEqual([1, 2, 3]);
  });

  it('第 maxPages 页仍 hasNext 时抛 SDR-E104', async () => {
    await expect(
      paginatePages({
        maxPages: 2,
        fetchPage: async () => ({ items: ['x'], hasNext: true }),
      }),
    ).rejects.toMatchObject({ code: ERROR_CODES.GITHUB_PAGINATION_OVERFLOW });
  });

  it('不返回部分结果：超限前已拉取页也不透出', async () => {
    let calls = 0;
    await expect(
      paginatePages({
        maxPages: 1,
        fetchPage: async () => {
          calls += 1;
          return { items: ['partial'], hasNext: true };
        },
      }),
    ).rejects.toThrow();
    expect(calls).toBe(1);
  });
});

import { SdrError, ERROR_CODES } from './errors.js';

const RETRY_DELAYS_MS = [1000, 2000, 4000] as const;
const NON_RETRYABLE_STATUSES = new Set([400, 401, 403, 404]);

export class HttpResponseError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(status: number, body: unknown) {
    super(`HTTP ${String(status)}`);
    this.name = 'HttpResponseError';
    this.status = status;
    this.body = body;
  }
}

function isRetryableStatus(status: number): boolean {
  if (NON_RETRYABLE_STATUSES.has(status)) return false;
  if (status === 408 || status === 429) return true;
  return status >= 500 && status <= 599;
}

export function maskToken(value: string): string {
  if (value.length <= 8) return '****';
  const head = value.slice(0, 3);
  const tail = value.slice(-3);
  return `${head}****${tail}`;
}

function maskSensitiveText(line: string): string {
  return line.replace(/[A-Za-z0-9_\-]{9,}/g, (token) => maskToken(token));
}

export interface RequestJsonOptions {
  readonly method?: string;
  readonly headers?: Readonly<Record<string, string>>;
  readonly body?: unknown;
  readonly timeoutMs?: number;
  readonly token?: string;
}

export type SleepFn = (ms: number) => Promise<void>;

const defaultSleep: SleepFn = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export interface HttpClient {
  requestJson<T>(url: string, options: RequestJsonOptions): Promise<T>;
}

export interface HttpClientDeps {
  readonly sleep?: SleepFn;
  readonly fetchImpl?: typeof fetch;
  readonly onLog?: (line: string) => void;
}

export function createHttpClient(deps: HttpClientDeps = {}): HttpClient {
  const sleep = deps.sleep ?? defaultSleep;
  const fetchImpl = deps.fetchImpl ?? fetch;
  const onLog = deps.onLog;

  const log = (line: string): void => {
    onLog?.(maskSensitiveText(line));
  };

  const requestJson = async <T>(url: string, options: RequestJsonOptions): Promise<T> => {
    const method = options.method ?? 'GET';
    const headers: Record<string, string> = {
      accept: 'application/json',
      ...options.headers,
    };
    if (options.token !== undefined) {
      headers.authorization = `Bearer ${options.token}`;
    }

    const init: RequestInit = { method, headers };
    if (options.body !== undefined) {
      headers['content-type'] = headers['content-type'] ?? 'application/json';
      init.body = typeof options.body === 'string' ? options.body : JSON.stringify(options.body);
    }

    if (options.token !== undefined) {
      log(`http ${method} ${url} token=${maskToken(options.token)}`);
    } else {
      log(`http ${method} ${url}`);
    }

    let lastError: unknown;
    const attempts = RETRY_DELAYS_MS.length + 1;

    for (let attempt = 0; attempt < attempts; attempt += 1) {
      try {
        const response = await fetchImpl(url, {
          ...init,
          signal: options.timeoutMs === undefined ? undefined : AbortSignal.timeout(options.timeoutMs),
        });

        const text = await response.text();
        let parsed: unknown = text;
        const contentType = response.headers.get('content-type') ?? '';
        if (contentType.includes('application/json') && text.length > 0) {
          parsed = JSON.parse(text) as unknown;
        }

        if (!response.ok) {
          if (!isRetryableStatus(response.status) || attempt === attempts - 1) {
            throw new HttpResponseError(response.status, parsed);
          }
          lastError = new HttpResponseError(response.status, parsed);
        } else {
          return parsed as T;
        }
      } catch (error) {
        if (error instanceof HttpResponseError) {
          if (!isRetryableStatus(error.status)) throw error;
          lastError = error;
        } else {
          lastError = error;
        }
        if (attempt === attempts - 1) {
          if (lastError instanceof HttpResponseError) throw lastError;
          throw lastError;
        }
      }

      const delay = RETRY_DELAYS_MS[attempt];
      if (delay !== undefined) await sleep(delay);
    }

    if (lastError instanceof HttpResponseError) throw lastError;
    throw lastError;
  };

  return { requestJson };
}

export const httpClient = createHttpClient();

export interface PageResult<T> {
  readonly items: readonly T[];
  readonly hasNext: boolean;
}

export interface PaginateOptions<T> {
  readonly fetchPage: (page: number) => Promise<PageResult<T>>;
  readonly maxPages?: number;
}

export async function paginatePages<T>(options: PaginateOptions<T>): Promise<T[]> {
  const maxPages = options.maxPages ?? 20;
  const collected: T[] = [];

  for (let page = 1; page <= maxPages; page += 1) {
    const { items, hasNext } = await options.fetchPage(page);
    collected.push(...items);
    if (!hasNext) return collected;
    if (page === maxPages) {
      throw new SdrError(ERROR_CODES.GITHUB_PAGINATION_OVERFLOW, 'pagination exceeded maxPages', {
        source: 'http',
      });
    }
  }

  return collected;
}

